function validate([grid]) {
  const m = grid.length;
  if (m < 1 || m > 20) return 'grid needs 1 to 20 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 20) return 'grid needs 1 to 20 columns.';
  if (grid.some(row => row.length !== n)) return 'Every row needs the same length.';
  if (m * n > 20) return 'grid has at most 20 cells in total.';
  let starts = 0, ends = 0;
  for (const row of grid) for (const v of row) {
    if (![-1, 0, 1, 2].includes(v)) return 'Each cell is -1, 0, 1 or 2.';
    if (v === 1) starts++;
    if (v === 2) ends++;
  }
  if (starts !== 1 || ends !== 1) return 'grid needs exactly one 1 (start) and one 2 (finish).';
  return null;
}

