function uniquePathsIII(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  let startRow = 0;
  let startCol = 0;
  let remaining = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 1) {
        startRow = r;
        startCol = c;
      }
      if (grid[r][c] !== -1) {
        remaining++;
      }
    }
  }

  function dfs(r, c, left) {
    if (grid[r][c] === 2) {
      return left === 1 ? 1 : 0;
    }
    const saved = grid[r][c];
    grid[r][c] = -1;
    const paths =
      (r + 1 < rows && grid[r + 1][c] !== -1 ? dfs(r + 1, c, left - 1) : 0) +
      (r > 0 && grid[r - 1][c] !== -1 ? dfs(r - 1, c, left - 1) : 0) +
      (c + 1 < cols && grid[r][c + 1] !== -1 ? dfs(r, c + 1, left - 1) : 0) +
      (c > 0 && grid[r][c - 1] !== -1 ? dfs(r, c - 1, left - 1) : 0);
    grid[r][c] = saved;
    return paths;
  }

  return dfs(startRow, startCol, remaining);
}

