function uniquePathsIII(grid) {
  // Count paths layer by layer: a state is (set of visited cells, current cell) with its number of ways.
  const rows = grid.length, cols = grid[0].length;
  const index = new Map(), cells = [];
  let start = -1, end = -1;
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    if (grid[r][c] === -1) continue;
    index.set(r * cols + c, cells.length);
    if (grid[r][c] === 1) start = cells.length;
    if (grid[r][c] === 2) end = cells.length;
    cells.push([r, c]);
  }
  let layer = new Map([[(1 << start) * 32 + start, 1]]);
  for (let step = 1; step < cells.length; step++) {
    const next = new Map();
    for (const [key, ways] of layer) {
      const cell = key % 32, mask = Math.floor(key / 32);
      if (cell === end) continue;
      const [r, c] = cells[cell];
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
        const k = index.get(nr * cols + nc);
        if (k === undefined || (mask & (1 << k))) continue;
        const nextKey = (mask | (1 << k)) * 32 + k;
        next.set(nextKey, (next.get(nextKey) || 0) + ways);
      }
    }
    layer = next;
  }
  return layer.get((2 ** cells.length - 1) * 32 + end) || 0;
}

