function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const shapes = size === 'large'
    ? [[4, 5], [5, 4], [2, 10], [10, 2], [3, 6], [6, 3], [1, 20], [4, 4], [2, 9]]
    : [[1, 2], [1, 5], [2, 2], [2, 3], [3, 2], [3, 3], [2, 4], [4, 2], [3, 4], [4, 3], [1, 8], [2, 5], [5, 1]];
  const [m, n] = shapes[pick(shapes.length)];
  const cells = m * n;
  const grid = Array.from({ length: m }, () => Array(n).fill(0));
  const at = k => [Math.floor(k / n), k % n];
  if (rand() < 0.5) {
    // A random self-avoiding walk; cells it misses become walls, so at least one path exists.
    const visited = new Set();
    let current = pick(cells);
    visited.add(current);
    for (;;) {
      const [r, c] = at(current);
      const options = [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]
        .filter(([a, b]) => a >= 0 && a < m && b >= 0 && b < n && !visited.has(a * n + b));
      if (!options.length || (visited.size >= 2 && rand() < 0.05)) break;
      const [a, b] = options[pick(options.length)];
      current = a * n + b;
      visited.add(current);
    }
    if (visited.size < 2) {
      const [r, c] = at(current);
      const [a, b] = c + 1 < n ? [r, c + 1] : c > 0 ? [r, c - 1] : r + 1 < m ? [r + 1, c] : [r - 1, c];
      current = a * n + b;
      visited.add(current);
    }
    const order = [...visited];
    for (let k = 0; k < cells; k++) if (!visited.has(k)) { const [r, c] = at(k); grid[r][c] = -1; }
    const [sr, sc] = at(order[0]);
    const [er, ec] = at(order[order.length - 1]);
    grid[sr][sc] = 1;
    grid[er][ec] = 2;
    return [grid];
  }
  const wallChance = size === 'large' ? 0.1 * rand() : 0.35 * rand();
  const start = pick(cells);
  let end = pick(cells - 1);
  if (end >= start) end++;
  for (let k = 0; k < cells; k++) {
    const [r, c] = at(k);
    if (k === start) grid[r][c] = 1;
    else if (k === end) grid[r][c] = 2;
    else if (rand() < wallChance) grid[r][c] = -1;
  }
  return [grid];
}
